/// ```text
/// Member = FieldDecl | PropertyDecl | IndexerDecl | FunctionDecl | ConstructorDecl | DestructorDecl | OperatorDecl | ConversionOperatorDecl | AssocTypeDecl | StructDecl | ClassDecl | RecordDecl | UnionDecl | EnumDecl | InterfaceDecl | SpliceMember
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Member {
    FieldDecl(FieldDecl),
    PropertyDecl(PropertyDecl),
    IndexerDecl(IndexerDecl),
    FunctionDecl(FunctionDecl),
    ConstructorDecl(ConstructorDecl),
    DestructorDecl(DestructorDecl),
    OperatorDecl(OperatorDecl),
    ConversionOperatorDecl(ConversionOperatorDecl),
    AssocTypeDecl(AssocTypeDecl),
    StructDecl(StructDecl),
    ClassDecl(ClassDecl),
    RecordDecl(RecordDecl),
    UnionDecl(UnionDecl),
    EnumDecl(EnumDecl),
    InterfaceDecl(InterfaceDecl),
    SpliceMember(SpliceMember),
}

impl AstNode for Member {
    fn can_cast(kind: SyntaxKind) -> bool {
        FieldDecl::can_cast(kind)
            || PropertyDecl::can_cast(kind)
            || IndexerDecl::can_cast(kind)
            || FunctionDecl::can_cast(kind)
            || ConstructorDecl::can_cast(kind)
            || DestructorDecl::can_cast(kind)
            || OperatorDecl::can_cast(kind)
            || ConversionOperatorDecl::can_cast(kind)
            || AssocTypeDecl::can_cast(kind)
            || StructDecl::can_cast(kind)
            || ClassDecl::can_cast(kind)
            || RecordDecl::can_cast(kind)
            || UnionDecl::can_cast(kind)
            || EnumDecl::can_cast(kind)
            || InterfaceDecl::can_cast(kind)
            || SpliceMember::can_cast(kind)
    }

    fn cast(node: SyntaxNode) -> Option<Self> {
        let kind = node.kind();
        if FieldDecl::can_cast(kind) {
            return FieldDecl::cast(node).map(Self::FieldDecl);
        }
        if PropertyDecl::can_cast(kind) {
            return PropertyDecl::cast(node).map(Self::PropertyDecl);
        }
        if IndexerDecl::can_cast(kind) {
            return IndexerDecl::cast(node).map(Self::IndexerDecl);
        }
        if FunctionDecl::can_cast(kind) {
            return FunctionDecl::cast(node).map(Self::FunctionDecl);
        }
        if ConstructorDecl::can_cast(kind) {
            return ConstructorDecl::cast(node).map(Self::ConstructorDecl);
        }
        if DestructorDecl::can_cast(kind) {
            return DestructorDecl::cast(node).map(Self::DestructorDecl);
        }
        if OperatorDecl::can_cast(kind) {
            return OperatorDecl::cast(node).map(Self::OperatorDecl);
        }
        if ConversionOperatorDecl::can_cast(kind) {
            return ConversionOperatorDecl::cast(node).map(Self::ConversionOperatorDecl);
        }
        if AssocTypeDecl::can_cast(kind) {
            return AssocTypeDecl::cast(node).map(Self::AssocTypeDecl);
        }
        if StructDecl::can_cast(kind) {
            return StructDecl::cast(node).map(Self::StructDecl);
        }
        if ClassDecl::can_cast(kind) {
            return ClassDecl::cast(node).map(Self::ClassDecl);
        }
        if RecordDecl::can_cast(kind) {
            return RecordDecl::cast(node).map(Self::RecordDecl);
        }
        if UnionDecl::can_cast(kind) {
            return UnionDecl::cast(node).map(Self::UnionDecl);
        }
        if EnumDecl::can_cast(kind) {
            return EnumDecl::cast(node).map(Self::EnumDecl);
        }
        if InterfaceDecl::can_cast(kind) {
            return InterfaceDecl::cast(node).map(Self::InterfaceDecl);
        }
        if SpliceMember::can_cast(kind) {
            return SpliceMember::cast(node).map(Self::SpliceMember);
        }
        None
    }

    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::FieldDecl(it) => it.syntax(),
            Self::PropertyDecl(it) => it.syntax(),
            Self::IndexerDecl(it) => it.syntax(),
            Self::FunctionDecl(it) => it.syntax(),
            Self::ConstructorDecl(it) => it.syntax(),
            Self::DestructorDecl(it) => it.syntax(),
            Self::OperatorDecl(it) => it.syntax(),
            Self::ConversionOperatorDecl(it) => it.syntax(),
            Self::AssocTypeDecl(it) => it.syntax(),
            Self::StructDecl(it) => it.syntax(),
            Self::ClassDecl(it) => it.syntax(),
            Self::RecordDecl(it) => it.syntax(),
            Self::UnionDecl(it) => it.syntax(),
            Self::EnumDecl(it) => it.syntax(),
            Self::InterfaceDecl(it) => it.syntax(),
            Self::SpliceMember(it) => it.syntax(),
        }
    }
}

